/** Р В Р’В Р РЋРЎвЂњР РЋР С“Р РЋР С“Р В РЎвЂќР В Р’В°Р РЋР РЏ Р РЋРІР‚С›Р В РЎвЂўР РЋР вЂљР В РЎВР В Р’В° Р В РЎВР В Р вЂ¦Р В РЎвЂўР В Р’В¶Р В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р вЂ Р В Р’ВµР В Р вЂ¦Р В Р вЂ¦Р В РЎвЂўР В РЎвЂ“Р В РЎвЂў Р РЋРІР‚РЋР В РЎвЂР РЋР С“Р В Р’В»Р В Р’В°: plural(5, 'Р РЋРІР‚РЋР В Р’В°Р РЋРІР‚С™', 'Р РЋРІР‚РЋР В Р’В°Р РЋРІР‚С™Р В Р’В°', 'Р РЋРІР‚РЋР В Р’В°Р РЋРІР‚С™Р В РЎвЂўР В Р вЂ ') Р Р†РІР‚В РІР‚в„ў 'Р РЋРІР‚РЋР В Р’В°Р РЋРІР‚С™Р В РЎвЂўР В Р вЂ '. */
function plural(n: number, one: string, few: string, many: string): string {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return few;
  return many;
}

