/**
 * Р В РЎСљР В Р’ВµР РЋР С“Р В РЎвЂќР В РЎвЂўР В Р’В»Р РЋР Р‰Р В РЎвЂќР В РЎвЂў Р В РўвЂР В Р’ВµР В РІвЂћвЂ“Р РЋР С“Р РЋРІР‚С™Р В Р вЂ Р В РЎвЂР В РІвЂћвЂ“ Р В Р’В°Р В РЎвЂ“Р В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р В РЎвЂўР В РўвЂР В Р вЂ¦Р В РЎвЂР В РЎВ Р В Р’В±Р В Р’В»Р В РЎвЂўР В РЎвЂќР В РЎвЂўР В РЎВ.
 *
 * Р В Р’В Р В Р’В°Р В Р вЂ¦Р РЋР Р‰Р РЋРІвЂљВ¬Р В Р’Вµ Р В РЎвЂќР В Р’В°Р В Р’В¶Р В РўвЂР РЋРІР‚в„–Р В РІвЂћвЂ“ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В·Р В РЎвЂўР В Р вЂ  Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р РЋР С“Р РЋРІР‚С™Р В Р’В°Р В Р вЂ¦Р В РЎвЂўР В Р вЂ Р В РЎвЂР В Р’В»Р РЋР С“Р РЋР РЏ Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В РЎВ Р РЋР С“Р В РЎвЂўР В РЎвЂўР В Р’В±Р РЋРІР‚В°Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’ВµР В РЎВ, Р В РЎвЂ Р В Р вЂ¦Р В Р’В°
 * Р РЋРЎвЂњР РЋР С“Р РЋРІР‚С™Р В Р’В°Р В Р вЂ¦Р В РЎвЂўР В Р вЂ Р В РЎвЂќР РЋРЎвЂњ Р В РўвЂР В Р’ВµР РЋР С“Р РЋР РЏР РЋРІР‚С™Р В РЎвЂ Р В РЎВР В РЎвЂўР В РўвЂР В РЎвЂўР В Р вЂ  Р В Р’В»Р В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р В РЎвЂ”Р РЋР вЂљР В Р’ВµР В Р вЂ Р РЋР вЂљР В Р’В°Р РЋРІР‚В°Р В Р’В°Р В Р’В»Р В Р’В°Р РЋР С“Р РЋР Р‰ Р В Р вЂ  Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋР С“Р РЋРІР‚С™Р РЋРІР‚в„–Р В Р вЂ¦Р РЋР вЂ№ Р В РЎвЂР В Р’В· Р вЂ™Р’В«Р В РЎвЂўР В РЎвЂќР вЂ™Р’В». Р В РЎС›Р В Р’ВµР В РЎвЂ”Р В Р’ВµР РЋР вЂљР РЋР Р‰
 * Р В РЎвЂ”Р В РЎвЂўР В РўвЂР РЋР вЂљР РЋР РЏР В РўвЂ Р В РЎвЂР В РўвЂР РЋРЎвЂњР РЋРІР‚В°Р В РЎвЂР В Р’Вµ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В·Р В РЎвЂўР В Р вЂ Р РЋРІР‚в„– Р РЋР С“Р В РЎвЂќР В Р’В»Р В Р’ВµР В РЎвЂР В Р вЂ Р В Р’В°Р РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ  Р В РЎвЂўР В РўвЂР В РЎвЂР В Р вЂ¦ Р В Р’В±Р В Р’В»Р В РЎвЂўР В РЎвЂќ: Р В РЎвЂ“Р В Р’В°Р В Р’В»Р В РЎвЂўР РЋРІР‚РЋР В РЎвЂќР В Р’В°, Р В Р’ВµР РЋР С“Р В Р’В»Р В РЎвЂ Р В Р вЂ Р РЋР С“Р РЋРІР‚В Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋРІвЂљВ¬Р В Р’В»Р В РЎвЂў,
 * Р В РЎвЂќР РЋР вЂљР В Р’ВµР РЋР С“Р РЋРІР‚С™Р В РЎвЂР В РЎвЂќ Р Р†Р вЂљРІР‚Сњ Р В Р’ВµР РЋР С“Р В Р’В»Р В РЎвЂ Р В Р’В±Р РЋРІР‚в„–Р В Р’В»Р В Р’В° Р В РЎвЂўР РЋРІвЂљВ¬Р В РЎвЂР В Р’В±Р В РЎвЂќР В Р’В°, Р В Р’В° Р В Р вЂ Р РЋР С“Р В Р’Вµ Р В РЎвЂР В Р’В·Р В РЎВР В Р’ВµР В Р вЂ¦Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р РЋРІР‚С›Р В Р’В°Р В РІвЂћвЂ“Р В Р’В»Р В РЎвЂўР В Р вЂ  Р РЋР С“Р В РЎвЂўР В Р’В±Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р РЋРІР‚в„– Р В Р вЂ Р В РЎВР В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р’Вµ.
 */
type MessageRow =
  | { kind: 'single'; key: string; messages: [ChatMessage] }
  | { kind: 'group'; key: string; items: ChatMessage[] };

/**
 * Р В Р Р‹Р В РЎвЂќР В Р’В»Р В Р’ВµР В РЎвЂР В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р В РЎвЂ”Р В РЎвЂўР В РўвЂР РЋР вЂљР РЋР РЏР В РўвЂ Р В РЎвЂР В РўвЂР РЋРЎвЂњР РЋРІР‚В°Р В РЎвЂР В Р’Вµ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В·Р В РЎвЂўР В Р вЂ Р РЋРІР‚в„– Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В РЎвЂўР В Р вЂ  Р В Р вЂ  Р В РЎвЂўР В РўвЂР В РЎвЂР В Р вЂ¦ Р В Р’В±Р В Р’В»Р В РЎвЂўР В РЎвЂќ, Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂўР В Р’В±Р РЋРІР‚в„– Р В Р’В»Р В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р В Р вЂ¦Р В Р’Вµ
 * Р В РЎвЂ”Р РЋР вЂљР В Р’ВµР В Р вЂ Р РЋР вЂљР В Р’В°Р РЋРІР‚В°Р В Р’В°Р В Р’В»Р В Р’В°Р РЋР С“Р РЋР Р‰ Р В Р вЂ  Р РЋР С“Р В РЎвЂ”Р В РЎвЂР РЋР С“Р В РЎвЂўР В РЎвЂќ Р вЂ™Р’В«Р В РЎвЂўР В РЎвЂќР вЂ™Р’В» Р В РЎвЂ”Р В РЎвЂўР РЋР С“Р В Р’В»Р В Р’Вµ Р В РЎвЂќР В Р’В°Р В Р’В¶Р В РўвЂР В РЎвЂўР В РЎвЂ“Р В РЎвЂў Р РЋРІвЂљВ¬Р В Р’В°Р В РЎвЂ“Р В Р’В°. Р В Р Р‹Р В Р’В°Р В РЎВР В РЎвЂ Р РЋР С“Р В РЎвЂўР В РЎвЂўР В Р’В±Р РЋРІР‚В°Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р В Р вЂ  Р В РЎВР В Р’В°Р РЋР С“Р РЋР С“Р В РЎвЂР В Р вЂ Р В Р’Вµ
 * Р В РЎвЂўР РЋР С“Р РЋРІР‚С™Р В Р’В°Р РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ¦Р В Р’ВµР РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р РЋРІР‚в„–Р В РЎВР В РЎвЂ: Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В РЎвЂќР В РЎвЂўР В Р’В» Р РЋРІР‚С™Р РЋР вЂљР В Р’ВµР В Р’В±Р РЋРЎвЂњР В Р’ВµР РЋРІР‚С™ Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В РІвЂћвЂ“ Р В РЎвЂўР РЋРІР‚С™Р В Р вЂ Р В Р’ВµР РЋРІР‚С™ Р В Р вЂ¦Р В Р’В° Р В РЎвЂќР В Р’В°Р В Р’В¶Р В РўвЂР РЋРІР‚в„–Р В РІвЂћвЂ“
 * tool_call_id, Р В РЎвЂ“Р РЋР вЂљР РЋРЎвЂњР В РЎвЂ”Р В РЎвЂ”Р В РЎвЂР РЋР вЂљР В РЎвЂўР В Р вЂ Р В РЎвЂќР В Р’В° Р РЋР С“Р РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р вЂ Р РЋРЎвЂњР В Р’ВµР РЋРІР‚С™ Р РЋРІР‚С™Р В РЎвЂўР В Р’В»Р РЋР Р‰Р В РЎвЂќР В РЎвЂў Р В РўвЂР В Р’В»Р РЋР РЏ Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В Р’В±Р РЋР вЂљР В Р’В°Р В Р’В¶Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ.
 */
function groupedMessages(messages: ChatMessage[]): MessageRow[] {
  const rows: MessageRow[] = [];
  for (const m of messages) {
    const prev = rows[rows.length - 1];
    if (m.role === 'tool' && prev?.kind === 'group') {
      prev.items.push(m);
      continue;
    }
    if (m.role === 'tool') {
      rows.push({ kind: 'group', key: `g-${m.id}`, items: [m] });
      continue;
    }
    rows.push({ kind: 'single', key: m.id, messages: [m] });
  }
  return rows;
}

/**
 * Р В Р’В­Р РЋРІР‚С›Р РЋРІР‚С›Р В Р’ВµР В РЎвЂќР РЋРІР‚С™ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р В РўвЂР В Р’В»Р РЋР РЏ Р В РЎвЂќР В Р’В°Р РЋР вЂљР РЋРІР‚С™Р В РЎвЂўР РЋРІР‚РЋР В РЎвЂќР В РЎвЂ Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В°.
 *
 * Р В Р’В Р В Р’В°Р В Р вЂ¦Р РЋР Р‰Р РЋРІвЂљВ¬Р В Р’Вµ Р В Р вЂ¦Р В Р’В° Р В РЎВР В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р’Вµ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В·Р В РЎвЂўР В Р вЂ Р В Р’В° Р РЋР С“Р РЋРІР‚С™Р В РЎвЂўР РЋР РЏР В Р’В»Р В Р’В° Р РЋРІР‚С™Р В РЎвЂўР В Р’В»Р РЋР Р‰Р В РЎвЂќР В РЎвЂў Р В РЎвЂР В РЎвЂќР В РЎвЂўР В Р вЂ¦Р В РЎвЂќР В Р’В°, Р В РЎвЂќР В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В Р’В°Р РЋР РЏ Р В Р вЂ¦Р В Р’Вµ Р В РЎВР В Р’ВµР В Р вЂ¦Р РЋР РЏР В Р’В»Р В Р’В°Р РЋР С“Р РЋР Р‰, Р В РЎвЂ”Р В РЎвЂўР РЋР РЉР РЋРІР‚С™Р В РЎвЂўР В РЎВР РЋРЎвЂњ
 * Р В Р вЂ Р В РЎвЂў Р В Р вЂ Р РЋР вЂљР В Р’ВµР В РЎВР РЋР РЏ Р В РўвЂР В РЎвЂўР В Р’В»Р В РЎвЂ“Р В РЎвЂўР В РІвЂћвЂ“ Р В РЎвЂ“Р В Р’ВµР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°Р РЋРІР‚В Р В РЎвЂР В РЎвЂ Р В РЎвЂќР В Р’В°Р РЋР вЂљР РЋРІР‚С™Р В РЎвЂўР РЋРІР‚РЋР В РЎвЂќР В Р’В° Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ“Р В Р’В»Р РЋР РЏР В РўвЂР В Р’ВµР В Р’В»Р В Р’В° Р вЂ™Р’В«Р В Р’В·Р В Р’В°Р В Р вЂ Р В РЎвЂР РЋР С“Р РЋРІвЂљВ¬Р В Р’ВµР В РІвЂћвЂ“Р вЂ™Р’В». Р В РЎС›Р В Р’ВµР В РЎвЂ”Р В Р’ВµР РЋР вЂљР РЋР Р‰ Р В Р вЂ Р В РЎвЂР В РўвЂР В Р вЂ¦Р В РЎвЂў, Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂў
 * Р В РЎвЂР В РЎВР В Р’ВµР В Р вЂ¦Р В Р вЂ¦Р В РЎвЂў Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В РЎвЂР РЋР С“Р РЋРІР‚В¦Р В РЎвЂўР В РўвЂР В РЎвЂР РЋРІР‚С™: Р В РЎвЂ“Р В Р’ВµР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°Р РЋРІР‚В Р В РЎвЂР РЋР РЏ Р В РЎвЂќР В Р’В°Р РЋР вЂљР РЋРІР‚С™Р В РЎвЂР В Р вЂ¦Р В РЎвЂќР В РЎвЂ Р Р†Р вЂљРІР‚Сњ Р В Р вЂ Р РЋР вЂљР В Р’В°Р РЋРІР‚В°Р В Р’В°Р РЋР вЂ№Р РЋРІР‚В°Р В РЎвЂР В РІвЂћвЂ“Р РЋР С“Р РЋР РЏ Р РЋРІвЂљВ¬Р В Р’В°Р РЋР вЂљ, Р РЋР вЂљР В Р’В°Р В Р’В±Р В РЎвЂўР РЋРІР‚С™Р В Р’В° Р РЋР С“ Р РЋРІР‚С›Р В Р’В°Р В РІвЂћвЂ“Р В Р’В»Р В Р’В°Р В РЎВР В РЎвЂ
 * Р В РЎвЂ Р В РЎвЂќР В РЎвЂўР В РўвЂР В РЎвЂўР В РЎВ Р Р†Р вЂљРІР‚Сњ Р В Р вЂ¦Р В Р’В°Р В РўвЂР В РЎвЂ”Р В РЎвЂР РЋР С“Р РЋР Р‰ Р В Р вЂ  Р РЋР вЂљР В Р’В°Р РЋР С“Р РЋРІР‚В¦Р В РЎвЂўР В РўвЂР РЋР РЏР РЋРІР‚В°Р В РЎвЂР РЋРІР‚В¦Р РЋР С“Р РЋР РЏ Р РЋР С“Р В Р’В»Р В РЎвЂўР РЋР РЏР РЋРІР‚В¦.
 */
/**
 * Р В РЎвЂєР РЋРІР‚РЋР В РЎвЂР РЋР С“Р РЋРІР‚С™Р В РЎвЂќР В Р’В° Р В РўвЂР В Р’В°Р В Р вЂ Р В Р вЂ¦Р В РЎвЂў Р В Р вЂ¦Р В Р’Вµ Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р РЋРІР‚в„–Р РЋРІР‚В¦ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В Р’ВµР В РЎвЂќР РЋРІР‚С™Р В РЎвЂўР В Р вЂ .
 *
 * Р В РЎС™Р В РЎвЂўР В РўвЂР В Р’В°Р В Р’В»Р В РЎвЂќР В Р’В° Р В Р вЂ¦Р В РЎвЂР РЋРІР‚РЋР В Р’ВµР В РЎвЂ“Р В РЎвЂў Р В Р вЂ¦Р В Р’Вµ Р РЋРЎвЂњР В РўвЂР В Р’В°Р В Р’В»Р РЋР РЏР В Р’ВµР РЋРІР‚С™ Р В Р вЂ Р РЋР С“Р В Р’В»Р В Р’ВµР В РЎвЂ”Р РЋРЎвЂњР РЋР вЂ№: Р РЋР С“Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’В°Р В Р’В»Р В Р’В° Р В РЎвЂ”Р В РЎвЂўР В РЎвЂќР В Р’В°Р В Р’В·Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р РЋР С“Р В РЎвЂ”Р В РЎвЂР РЋР С“Р В РЎвЂўР В РЎвЂќ Р РЋР С“ Р РЋР вЂљР В Р’В°Р В Р’В·Р В РЎВР В Р’ВµР РЋР вЂљР В Р’В°Р В РЎВР В РЎвЂ Р В РЎвЂ
 * Р В РўвЂР В Р’В°Р РЋРІР‚С™Р В РЎвЂўР В РІвЂћвЂ“, Р В РЎвЂР В РЎвЂ“Р РЋР вЂљР В РЎвЂўР В РЎвЂќ Р В РЎвЂўР РЋРІР‚С™Р В РЎВР В Р’ВµР РЋРІР‚РЋР В Р’В°Р В Р’ВµР РЋРІР‚С™ Р В Р вЂ¦Р РЋРЎвЂњР В Р’В¶Р В Р вЂ¦Р В РЎвЂўР В Р’Вµ Р В РЎвЂ Р В Р’В¶Р В РЎВР РЋРІР‚ВР РЋРІР‚С™ Р вЂ™Р’В«Р В Р в‚¬Р В РўвЂР В Р’В°Р В Р’В»Р В РЎвЂР РЋРІР‚С™Р РЋР Р‰Р вЂ™Р’В». Р В РЎСџР РЋРЎвЂњР РЋРІР‚С™Р В РЎвЂ Р В РўвЂР В РЎвЂўР В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р В РЎвЂР РЋРІР‚С™Р В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂў
 * Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР РЏР РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ¦Р В Р’В° Rust-Р РЋР С“Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂўР В Р вЂ¦Р В Р’Вµ, Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂўР В Р’В±Р РЋРІР‚в„– Р В РЎвЂўР В РЎвЂ”Р В Р’ВµР РЋРІР‚РЋР В Р’В°Р РЋРІР‚С™Р В РЎвЂќР В Р’В° Р В Р вЂ¦Р В Р’Вµ Р РЋРЎвЂњР В РўвЂР В Р’В°Р В Р’В»Р В РЎвЂР В Р’В»Р В Р’В° Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂў-Р РЋРІР‚С™Р В РЎвЂў Р В Р вЂ Р В Р вЂ¦Р В Р’Вµ Projects.
 */
function ToolPendingLoader({ tool }: { tool: string }) {
  const isImage = tool === 'generate_image';
  const isCode = /write_text|edit_file|read_text|write_file|search_code|list_dir/.test(tool);
  if (isImage) return <ImageGenLoader label="Р В РІР‚СљР В Р’ВµР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°Р РЋРІР‚В Р В РЎвЂР РЋР РЏ" size={26} />;
  if (isCode) return <CodeGenLoader label="Р В РЎСџР РЋР вЂљР В Р’В°Р В Р вЂ Р В РЎвЂќР В Р’В°" size={96} />;
  return <WaveLoader bars={4} label="Р В РІР‚в„ўР РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ" />;
}

function ToolGroup({ items, onInstalled }: { items: ChatMessage[]; onInstalled?: (text: string) => void }) {
  const [open, setOpen] = useState(false);
  // Р В РЎСџР В РЎвЂўР В РЎвЂќР В Р’В° Р В Р’В°Р В РЎвЂ“Р В Р’ВµР В Р вЂ¦Р РЋРІР‚С™ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В·Р В РЎвЂўР В Р вЂ , Р РЋРЎвЂњ Р РЋР С“Р В РЎвЂўР В РЎвЂўР В Р’В±Р РЋРІР‚В°Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ-Р В Р’В·Р В Р’В°Р В РЎвЂ“Р В Р’В»Р РЋРЎвЂњР РЋРІвЂљВ¬Р В РЎвЂќР В РЎвЂ Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋР С“Р РЋРІР‚С™ Р вЂ™Р’В«Р Р†Р вЂљР’В¦ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р Р†Р вЂљР’В¦Р вЂ™Р’В».
  const pending = items.some(m => m.content === 'Р Р†Р вЂљР’В¦ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р Р†Р вЂљР’В¦');
  const hasError = items.some(m => m.error);
  const cards = items.flatMap(m => (m.error ? [] : (m.cards ?? [])));
  const changes = items.flatMap(m => m.changes ?? []);
  const browser = [...items].reverse().find(m => m.browser)?.browser;
  const totalChanges = changes.length;
  const one = items.length === 1;

  return (
    <div className="ore-plain mb-2 overflow-hidden rounded-lg border"
      style={{ borderColor: hasError ? 'var(--color-error)' : 'var(--color-border)', background: 'var(--color-surface-2)' }}>
      <button onClick={() => setOpen(o => !o)}
        className="flex w-full items-center gap-2 px-2.5 py-1.5 text-left text-[11px] font-semibold"
        style={{ color: hasError ? 'var(--color-error)' : 'var(--color-text-secondary)' }}>
        <ChevronRight size={11} className={`transition-transform ${open ? 'rotate-90' : ''}`} />
        <span className="openportal-action-icon" style={{ color: hasError ? 'var(--color-error)' : pending ? 'var(--color-primary)' : 'var(--color-success)' }}>
          {actionIcon(items[0]?.toolName ?? 'agent', hasError, pending)}
        </span>
        <span className="truncate">
          {one ? (items[0]?.toolName ?? 'Р В РўвЂР В Р’ВµР В РІвЂћвЂ“Р РЋР С“Р РЋРІР‚С™Р В Р вЂ Р В РЎвЂР В Р’Вµ') : `Р В РІР‚в„ўР РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р В Р’ВµР В Р вЂ¦Р В РЎвЂў Р В РўвЂР В Р’ВµР В РІвЂћвЂ“Р РЋР С“Р РЋРІР‚С™Р В Р вЂ Р В РЎвЂР В РІвЂћвЂ“: ${items.length}`}
        </span>
        {totalChanges > 0 && (
          <span className="rounded px-1 text-[9px] font-bold"
            style={{ background: 'var(--color-surface)', color: 'var(--color-text-tertiary)' }}>
            {totalChanges} {totalChanges === 1 ? 'Р РЋРІР‚С›Р В Р’В°Р В РІвЂћвЂ“Р В Р’В»' : 'Р РЋРІР‚С›Р В Р’В°Р В РІвЂћвЂ“Р В Р’В»Р В РЎвЂўР В Р вЂ '}
          </span>
        )}
        {cards.length > 0 && (
          <span className="rounded px-1 text-[9px] font-bold"
            style={{ background: 'var(--color-surface)', color: 'var(--color-text-tertiary)' }}>{cards.length}</span>
        )}
        <span className="ml-auto shrink-0 font-normal" style={{ color: 'var(--color-text-tertiary)' }}>
          {pending ? 'Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏР Р†Р вЂљР’В¦' : hasError ? 'Р РЋР С“ Р В РЎвЂўР РЋРІвЂљВ¬Р В РЎвЂР В Р’В±Р В РЎвЂќР В РЎвЂўР В РІвЂћвЂ“' : 'Р В РЎвЂ“Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В Р вЂ Р В РЎвЂў'}
        </span>
      </button>

      {browser && (
        <div className="border-t p-1.5" style={{ borderColor: 'var(--color-border)' }}>
          <BrowserView card={browser} />
        </div>
      )}

      {changes.length > 0 && <FileChanges changes={changes} />}

      {cards.length > 0 && (
        <div className="grid gap-1.5 border-t p-1.5" style={{ borderColor: 'var(--color-border)' }}>
          <CardGrid cards={cards} onInstalled={onInstalled} />
        </div>
      )}

      <AnimatePresence>
      {open && (
        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }}
          className="max-h-72 overflow-y-auto border-t" style={{ borderColor: 'var(--color-border)' }}>
          {items.map(m => {
            const imgMatch = m.toolName === 'generate_image'
              ? /\/op-image\/([A-Za-z0-9-]+\.(?:png|jpg|jpeg|webp|gif|avif|heic))/i.exec(m.content) : null;
            return (
              <div key={m.id} className="border-b px-2.5 py-1.5 last:border-b-0" style={{ borderColor: 'var(--color-border)' }}>
                <div className="flex items-center gap-1.5 text-[10px] font-bold"
                  style={{ color: m.error ? 'var(--color-error)' : 'var(--color-text-secondary)' }}>
                  <span className="openportal-action-icon" style={{ color: m.error ? 'var(--color-error)' : 'var(--color-success)' }}>
                    {actionIcon(m.toolName ?? 'agent', Boolean(m.error), m.content === 'Р Р†Р вЂљР’В¦ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р Р†Р вЂљР’В¦')}
                  </span>
                  {m.toolName}
                </div>
                {imgMatch && !m.error && <div className="openportal-image-result pt-1.5"><div className="mb-1 flex items-center gap-1.5 text-[10px] font-bold" style={{ color: 'var(--color-text-secondary)' }}><ImageIcon size={11} style={{ color: 'var(--grad-glow)' }} /> Р В Р’В Р В Р’ВµР В Р’В·Р РЋРЎвЂњР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™ Р В РЎвЂ“Р В Р’ВµР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°Р РЋРІР‚В Р В РЎвЂР В РЎвЂ Р В РЎвЂР В Р’В·Р В РЎвЂўР В Р’В±Р РЋР вЂљР В Р’В°Р В Р’В¶Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ</div><PortalImage name={imgMatch[1]} /></div>}
                <pre className="mt-1 whitespace-pre-wrap font-mono text-[10px] leading-4"
                  style={{ color: 'var(--color-text-secondary)' }}>{m.content}</pre>
              </div>
            );
          })}
        </motion.div>
      )}
      </AnimatePresence>
    </div>
  );
}

