  const [found, setFound] = useState<ModCard[]>([]);
  const messageCards = useMemo(
    () => messages.flatMap(m => m.cards ?? []),
    [messages],
  );
  useEffect(() => {
    if (messageCards.length === 0) return;
    setFound(prev => {
      const merged = [...prev];
      const seen = new Set(prev.map(c => `${c.projectId}|${c.versionNumber}`));
      for (const c of messageCards) {
        const key = `${c.projectId}|${c.versionNumber}`;
        if (!seen.has(key)) { seen.add(key); merged.push(c); }
      }
      return merged.length === prev.length ? prev : merged;
    });
  }, [messageCards]);

  const mentionOf = useCallback((card: ModCard) => {
    setFound(prev => (prev.some(c => c.projectId === card.projectId && c.versionNumber === card.versionNumber) ? prev : [...prev, card]));
    setInput(prev => {
      const at = prev.lastIndexOf('@');
      // Р В РІР‚СћР РЋР С“Р В Р’В»Р В РЎвЂ @ Р РЋРЎвЂњР В Р’В¶Р В Р’Вµ Р В Р’ВµР РЋР С“Р РЋРІР‚С™Р РЋР Р‰ Р В РЎвЂ Р В РЎвЂўР В Р вЂ¦ Р вЂ™Р’В«Р РЋР С“Р В Р вЂ Р В Р’ВµР В Р’В¶Р В РЎвЂР В РІвЂћвЂ“Р вЂ™Р’В», Р В РўвЂР В РЎвЂўР В РЎвЂ”Р В РЎвЂР РЋР С“Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР В РЎВ Р В РЎвЂ”Р В РЎвЂўР РЋР С“Р В Р’В»Р В Р’Вµ Р В Р вЂ¦Р В Р’ВµР В РЎвЂ“Р В РЎвЂў.
      if (at >= 0 && !prev.slice(at + 1).includes(' ')) {
        return prev.slice(0, at) + `@${card.slug} `;
      }
      return `${prev}${prev ? ' ' : ''}@${card.slug} `;
    });
    composerRef.current?.focus();
  }, []);

  // Р В РЎСџР В РЎвЂўР В РўвЂР РЋР С“Р В РЎвЂќР В Р’В°Р В Р’В·Р В РЎвЂќР В РЎвЂ Р В РЎвЂ”Р В РЎвЂў @: Р В РЎвЂР РЋРІР‚В°Р В Р’ВµР В РЎВ Р В РЎвЂ”Р В РЎвЂўР РЋР С“Р В Р’В»Р В Р’ВµР В РўвЂР В Р вЂ¦Р В Р’ВµР В Р’Вµ Р вЂ™Р’В«@Р РЋР С“Р В Р’В»Р В РЎвЂўР В Р вЂ Р В РЎвЂўР вЂ™Р’В» Р В Р вЂ  Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р’Вµ Р В Р вЂ Р В Р вЂ Р В РЎвЂўР В РўвЂР В Р’В°.
